<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1, user-scalable=no">
<title>Falling Sand Sandbox</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body {
    background: #0a0a12;
    color: #d0d0d0;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    min-height: 100vh;
  }
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 16px 8px;
    user-select: none;
    -webkit-user-select: none;
  }
  h1 {
    font-size: 15px;
    font-weight: 600;
    margin-bottom: 12px;
    letter-spacing: 2.5px;
    color: #888;
    text-transform: uppercase;
  }
  #controls {
    display: flex;
    gap: 5px;
    margin-bottom: 14px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    background: #16161e;
    color: #9090a0;
    border: 1px solid #252530;
    padding: 8px 11px;
    border-radius: 3px;
    cursor: pointer;
    font-size: 11px;
    font-family: inherit;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 500;
    transition: all 0.12s ease;
    display: flex;
    align-items: center;
  }
  button:hover { background: #1f1f2c; color: #c8c8d8; }
  button.active {
    background: #2a2a44;
    color: #fff;
    border-color: #5a6ca0;
    box-shadow: 0 0 8px rgba(90,108,160,0.3);
  }
  #clear { border-color: #4a2a2a; }
  #clear:hover { background: #2e1e1e; color: #d0a0a0; }
